import hashlib
def link(prev, data):
    return hashlib.sha256((prev + data).encode()).hexdigest()
def build(items):
    hs, prev = [], 'genesis'
    for d in items:
        prev = link(prev, d)
        hs.append(prev)
    return hs
data = ['Joe pays Alice 1', 'Alice pays Eve 2', 'Eve pays Joe 3']
stored = build(data)
tampered = ['Joe pays Alice 100'] + data[1:]
print((build(data) == stored, build(tampered) == stored))

